<script setup lang="ts">import {ref} from 'vue';import type {User,Run} from '../types/domain';import {useRoute} from '../hooks/useRoute';import {useCorpora} from '../stores/corpora';import {useResearch} from '../stores/research';import Layout from '../components/Layout.vue';import Notice from '../components/common/Notice.vue';import Overview from '../pages/Overview.vue';import Sources from '../pages/Sources.vue';import Config from '../pages/Config.vue';import Results from '../pages/Results.vue';import Notes from '../pages/Notes.vue';import Audit from '../pages/Audit.vue';defineProps<{user:User}>();defineEmits(['logout']);const page=useRoute(),data=useCorpora(),research=useResearch(),selectedId=ref(0);function select(run:Run){selectedId.value=run.id;location.hash='results'}</script><template><Layout :user="user" :page="page" @logout="$emit('logout')"><Notice :error="data.state.error||research.state.error"/><Sources v-if="page==='sources'" :corpora="data.state.corpora" :documents="data.state.documents" :whitelist="data.state.whitelist" :user="user" :reload="data.reload"/><Config v-else-if="page==='config'" :corpora="data.state.corpora" :runs="research.state.runs" :user="user" :reload="research.reload" @select="select"/><Results v-else-if="page==='results'" :runs="research.state.runs" :profiles="research.state.profiles" :selected-id="selectedId" :user="user" :reload="research.reload" @select="select"/><Notes v-else-if="page==='notes'" :notes="research.state.notes" :user="user" :reload="research.reload"/><Audit v-else-if="page==='audit'"/><Overview v-else :corpora="data.state.corpora" :runs="research.state.runs" :profiles="research.state.profiles" :notes="research.state.notes" @select="select"/></Layout></template>
